import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let uri = request.get("path") as? String
        if let u = uri {
            if !is_start_with(u) {
                return false
            }
        } else {
            return false
        }

        let userOption = get_jwt_user(request)
        if let user = userOption {
            set_current_user_info_and_log(user)
            return true
        } else {
            return false
        }
    }

    public func is_start_with(request_uri: String): Bool {
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headersOption = request.get("headers") as? HashMap<String, Any>
        if let headers = headersOption {
            let authOption = headers.get("Authorization") as? HashMap<String, Any>
            if let auth = authOption {
                let jwtOption = auth.get("jwt") as? String
                let userOption = auth.get("user") as? HashMap<String, Any>
                if let jwt = jwtOption, let user = userOption {
                    let today = DateTime.now().format("yyyy-MM-dd")
                    let expectedJwt = (user.get("name") as? String ?? "") + today
                    if jwt == expectedJwt {
                        return Some(user)
                    }
                }
            }
        }
        return None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // Simulate setting current user info and logging
        let userName = user.get("name") as? String ?? "Unknown"
        let address = user.get("address") as? String ?? "Unknown"
        println("User: " + userName + " from " + address + " accessed the system at " + DateTime.now().toString())
    }
}

