import std.collection.ArrayList

class AvgPartition {
    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        if (limit <= 0) {
            panic("Number of partitions must be greater than 0")
        }
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        let size = this.lst.size
        let block_size = size / this.limit
        let remainder = size % this.limit
        return (block_size, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        if (index < 0 || index >= this.limit) {
            panic("Index out of bounds")
        }

        let (block_size, remainder) = this.setNum()
        let start = index * block_size + (index < remainder ? index : remainder)
        let end = start + block_size + (index < remainder ? 1 : 0)

        return this.lst[start..<end]
    }
}

