class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        var result = [Int8]()
        var carry: Int8 = 0
        var i = num1.length() - 1
        var j = num2.length() - 1

        while i >= 0 || j >= 0 || carry != 0 {
            var digit1: Int8 = 0
            var digit2: Int8 = 0

            if i >= 0 {
                digit1 = Int8.parse(String(num1[i])) ?? 0
                i = i - 1
            }

            if j >= 0 {
                digit2 = Int8.parse(String(num2[j])) ?? 0
                j = j - 1
            }

            let sum = digit1 + digit2 + carry
            result.append(sum % 10)
            carry = sum / 10
        }

        var resultStr = ""
        for k in (0..<result.length()).reversed() {
            resultStr = resultStr + String(result[k])
        }

        return resultStr
    }

    public static func subtract(num1: String, num2: String): String {
        var result = [Int8]()
        var borrow: Int8 = 0
        var i = num1.length() - 1
        var j = num2.length() - 1

        while i >= 0 || j >= 0 {
            var digit1: Int8 = 0
            var digit2: Int8 = 0

            if i >= 0 {
                digit1 = Int8.parse(String(num1[i])) ?? 0
                i = i - 1
            }

            if j >= 0 {
                digit2 = Int8.parse(String(num2[j])) ?? 0
                j = j - 1
            }

            var diff = digit1 - digit2 - borrow
            if diff < 0 {
                diff = diff + 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.append(diff)
        }

        var resultStr = ""
        var leadingZero = true
        for k in (0..<result.length()).reversed() {
            if result[k] != 0 {
                leadingZero = false
            }
            if !leadingZero {
                resultStr = resultStr + String(result[k])
            }
        }

        if resultStr == "" {
            resultStr = "0"
        }

        return resultStr
    }

    public static func multiply(num1: String, num2: String): String {
        var result = [Int8](repeating: 0, count: num1.length() + num2.length())

        for i in (0..<num1.length()).reversed() {
            for j in (0..<num2.length()).reversed() {
                let digit1 = Int8.parse(String(num1[i])) ?? 0
                let digit2 = Int8.parse(String(num2[j])) ?? 0
                let product = digit1 * digit2
                let pos1 = i + j
                let pos2 = i + j + 1
                let sum = product + result[pos2]

                result[pos1] = result[pos1] + sum / 10
                result[pos2] = sum % 10
            }
        }

        var resultStr = ""
        var leadingZero = true
        for digit in result {
            if digit != 0 {
                leadingZero = false
            }
            if !leadingZero {
                resultStr = resultStr + String(digit)
            }
        }

        if resultStr == "" {
            resultStr = "0"
        }

        return resultStr
    }
}

