import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File(Path(file_name))
        let reader = TextReader(file)
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()
        var line_count = 0

        while (true) {
            let line = reader.readLine()
            if (line == null) {
                break
            }

            let row = line.split(',')
            if (line_count == 0) {
                title = ArrayList<String>(row)
            } else {
                data.add(ArrayList<String>(row))
            }
            line_count += 1
        }

        reader.close()
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(Path(file_name))
        let writer = TextWriter(file)

        for (row in data) {
            let line = row.join(",")
            writer.writeLine(line)
        }

        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)

        for (row in data) {
            if (N < row.size()) {
                let processed_value = row[N.toInt32()].to_uppercase()
                let new_row = ArrayList<String>()
                new_row.add(processed_value)
                new_data.add(new_row)
            }
        }

        let save_path = save_file_name + "_process.csv"
        return write_csv(new_data, save_path)
    }
}

