        let n = this.data.size()
        if (n <= 1) {
            return 0.0
        }

        let meanX = this.get_sum() / Float64(n)
        let meanY = (Float64(n) + 1.0) / 2.0

        var numerator = 0.0
        var denominatorX = 0.0
        var denominatorY = 0.0

        for (i in 0..n) {
            let x = this.data[i]
            let y = Float64(i + 1)
            numerator += (x - meanX) * (y - meanY)
            denominatorX += (x - meanX) ** 2
            denominatorY += (y - meanY) ** 2
        }

        if (denominatorX == 0.0 || denominatorY == 0.0) {
            return 0.0
        }

        return numerator / sqrt(denominatorX * denominatorY)
    }
}
