import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        if n != data2.size() || n == 0 {
            return 0.0
        }

        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        var sum1_sq: Float64 = 0.0
        var sum2_sq: Float64 = 0.0
        var product_sum: Float64 = 0.0

        for i in 0..<n {
            let x = data1.get(i)
            let y = data2.get(i)
            sum1 += x
            sum2 += y
            sum1_sq += x * x
            sum2_sq += y * y
            product_sum += x * y
        }

        let numerator = n * product_sum - sum1 * sum2
        let denominator = sqrt((n * sum1_sq - sum1 * sum1) * (n * sum2_sq - sum2 * sum2))

        if denominator == 0.0 {
            return 0.0
        }

        return numerator / denominator
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if n < 2 {
            return 0.0
        }

        var mean: Float64 = 0.0
        for i in 0..<n {
            mean += data.get(i)
        }
        mean /= n

        var m2: Float64 = 0.0
        var m3: Float64 = 0.0
        for i in 0..<n {
            let diff = data.get(i) - mean
            m2 += diff * diff
            m3 += diff * diff * diff
        }

        m2 /= n
        m3 /= n

        if m2 == 0.0 {
            return 0.0
        }

        let std_dev = sqrt(m2)
        return m3 / (std_dev * std_dev * std_dev)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        if n < 2 {
            return 0.0
        }

        var mean: Float64 = 0.0
        for i in 0..<n {
            mean += data.get(i)
        }
        mean /= n

        var m2: Float64 = 0.0
        var m4: Float64 = 0.0
        for i in 0..<n {
            let diff = data.get(i) - mean
            let diff_sq = diff * diff
            m2 += diff_sq
            m4 += diff_sq * diff_sq
        }

        m2 /= n
        m4 /= n

        if m2 == 0.0 {
            return 0.0
        }

        return (m4 / (m2 * m2)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let coeff = 1.0 / (sqrt(2.0 * 3.141592653589793) * sigma)

        for i in 0..<data.size() {
            let x = data.get(i)
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            let density = coeff * exp(exponent)
            result.add(density)
        }

        return result
    }
}

