import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var result = ""
        for (char in ciphertext) {
            if (('a' <= char && char <= 'z') || ('A' <= char && char <= 'Z')) {
                let is_upper = ('A' <= char && char <= 'Z')
                let base = is_upper ? 'A' : 'a'
                let shifted = ((char - base - shift) % 26 + 26) % 26
                result += (shifted + base) as Char
            } else {
                result += char
            }
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var result = ""
        var key_index = 0
        let key_len = this.key.size()
        if (key_len == 0) {
            return ciphertext
        }
        for (char in ciphertext) {
            if (('a' <= char && char <= 'z') || ('A' <= char && char <= 'Z')) {
                let is_upper = ('A' <= char && char <= 'Z')
                let base = is_upper ? 'A' : 'a'
                let key_char = this.key[key_index % key_len]
                let key_base = ('A' <= key_char && key_char <= 'Z') ? 'A' : 'a'
                let shift = (key_char - key_base)
                let decrypted = ((char - base - shift) % 26 + 26) % 26
                result += (decrypted + base) as Char
                key_index += 1
            } else {
                result += char
            }
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        let n = encrypted_text.size()
        if (n == 0 || rails <= 1) {
            return encrypted_text
        }

        // Create rails
        let rail_list = ArrayList<ArrayList<Char>>()
        for (i in 0..<rails) {
            rail_list.add(ArrayList<Char>())
        }

        // Mark positions with '*'
        var rail = 0
        var step = 1
        for (i in 0..<n) {
            rail_list[rail].add('*')
            if (rail == 0) {
                step = 1
            } else if (rail == (rails - 1)) {
                step = -1
            }
            rail += step
        }

        // Fill the rails with encrypted chars
        var index = 0
        let chars = encrypted_text.toChars()
        for (i in 0..<rails) {
            let size = rail_list[i].size()
            for (j in 0..<size) {
                rail_list[i][j] = chars[index]
                index += 1
            }
        }

        // Read in zigzag order
        var result_chars = ArrayList<Char>()
        rail = 0
        step = 1
        var pos_list = ArrayList<Int64>()
        for (i in 0..<rails) {
            pos_list.add(0)
        }

        for (i in 0..<n) {
            result_chars.add(rail_list[rail][pos_list[rail]])
            pos_list[rail] += 1
            if (rail == 0) {
                step = 1
            } else if (rail == (rails - 1)) {
                step = -1
            }
            rail += step
        }

        return result_chars.collectString()
    }
}

