            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0 .. state.size) {
            for (j in 0 .. state[i].size) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (0, 0)  // 此行理论上不会执行
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let blank = this.find_blank(state)
        let (x, y) = blank
        var new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.add(ArrayList<Int64>(row))
        }

        if (direction == "up" && x > 0) {
            new_state[x][y] = new_state[x - 1][y]
            new_state[x - 1][y] = 0
        } else if (direction == "down" && x < 2) {
            new_state[x][y] = new_state[x + 1][y]
            new_state[x + 1][y] = 0
        } else if (direction == "left" && y > 0) {
            new_state[x][y] = new_state[x][y - 1]
            new_state[x][y - 1] = 0
        } else if (direction == "right" && y < 2) {
            new_state[x][y] = new_state[x][y + 1]
            new_state[x][y + 1] = 0
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (x, y) = this.find_blank(state)
        var moves = ArrayList<String>()
        if (x > 0) { moves.add("up") }
        if (x < 2) { moves.add("down") }
        if (y > 0) { moves.add("left") }
        if (y < 2) { moves.add("right") }
        return moves
    }

    func state_to_string(state: ArrayList<ArrayList<Int64>>): String {
        var res = ""
        for (row in state) {
            for (item in row) {
                res = res.concat(item.toString())
            }
        }
        return res
    }

    public func solve(): ArrayList<String> {
        var queue = LinkedListQueue<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        var visited = HashMap<String, Bool>()

        queue.enqueue((this.initial_state, ArrayList<String>()))
        visited[this.state_to_string(this.initial_state)] = true

        while (!queue.isEmpty()) {
            let (current_state, path) = queue.dequeue()
            if (current_state == this.goal_state) {
                return path
            }

            let moves = this.get_possible_moves(current_state)
            for (move_dir in moves) {
                let new_state = this.move(current_state, move_dir)
                let state_str = this.state_to_string(new_state)
                if (!visited.containsKey(state_str)) {
                    visited[state_str] = true
                    var new_path = ArrayList<String>(path)
                    new_path.add(move_dir)
                    queue.enqueue((new_state, new_path))
                }
            }
        }
        return ArrayList<String>()  // 无解情况
    }
}
