import std.collection.ArrayList

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (let i = 0; i < x_interp.size(); i = i + 1) {
            let xi = x_interp[i]
            var yi: Float64 = 0.0
            var j: Int64 = 0
            while (j < x.size() - 1 && x[j + 1] < xi) {
                j = j + 1
            }
            if (j >= x.size() - 1) {
                j = x.size() - 2
            }
            let x0 = x[j]
            let x1 = x[j + 1]
            let y0 = y[j]
            let y1 = y[j + 1]
            if (x1 - x0 != 0.0) {
                yi = y0 + (y1 - y0) * (xi - x0) / (x1 - x0)
            } else {
                yi = y0
            }
            result.add(yi)
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (let i = 0; i < x_interp.size(); i = i + 1) {
            let xi = x_interp[i]
            let yi = y_interp[i]
            var j: Int64 = 0
            while (j < x.size() - 1 && x[j + 1] < xi) {
                j = j + 1
            }
            if (j >= x.size() - 1) {
                j = x.size() - 2
            }
            var k: Int64 = 0
            while (k < y.size() - 1 && y[k + 1] < yi) {
                k = k + 1
            }
            if (k >= y.size() - 1) {
                k = y.size() - 2
            }
            let x0 = x[j]
            let x1 = x[j + 1]
            let y0 = y[k]
            let y1 = y[k + 1]
            let z00 = z[j][k]
            let z01 = z[j][k + 1]
            let z10 = z[j + 1][k]
            let z11 = z[j + 1][k + 1]

            let zx0 = z00 + (z10 - z00) * (xi - x0) / (x1 - x0)
            let zx1 = z01 + (z11 - z01) * (xi - x0) / (x1 - x0)
            let zi = zx0 + (zx1 - zx0) * (yi - y0) / (y1 - y0)
            result.add(zi)
        }
        return result
    }
}

