import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let octets = this.ip_address.split('.')
        if (octets.size != 4) {
            return false
        }
        for octet in octets {
            if (octet.isEmpty || (octet.size > 1 && octet.get(0) == '0')) {
                return false
            }
            for c in octet {
                if (!c.isDigit()) {
                    return false
                }
            }
            let num = Int64.parse(octet)
            if (num < 0 || num > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        let result = ArrayList<String>()
        if (!this.is_valid()) {
            return result
        }
        let octets = this.ip_address.split('.')
        for octet in octets {
            result.add(octet)
        }
        return result
    }

    public func get_binary(): String {
        if (!this.is_valid()) {
            return ""
        }
        let octets = this.ip_address.split('.')
        let binary_octets = ArrayList<String>()
        for octet in octets {
            let num = UInt8.parse(octet)
            let binary = num.format("08b")
            binary_octets.add(binary)
        }
        return binary_octets.join(".")
    }
}

