import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var total = 0.0
        var agree = 0.0

        for (i in 0..testData.size()) {
            let row = testData[i]
            for (j in 0..row.size()) {
                let val = Float64(row[j])
                total += val
                if (i == j) {
                    agree += val
                }
            }
        }

        let pObserved = agree / total

        var pExpected = 0.0
        var rowSums = ArrayList<Float64>()
        var colSums = ArrayList<Float64>()

        for (i in 0..k) {
            var rowSum = 0.0
            var colSum = 0.0
            for (j in 0..k) {
                rowSum += Float64(testData[i][j])
                colSum += Float64(testData[j][i])
            }
            rowSums.add(rowSum)
            colSums.add(colSum)
        }

        for (i in 0..k) {
            pExpected += (rowSums[i] * colSums[i]) / (total * total)
        }

        if (abs(pExpected - 1.0) < 1e-10) {
            return 1.0
        }

        let kappa = (pObserved - pExpected) / (1.0 - pExpected)
        return kappa
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var pj = ArrayList<Float64>()
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += Float64(testData[i][j])
            }
            pj.add(sum / (Float64(N) * Float64(n)))
        }

        var Pbar = 0.0
        for (i in 0..N) {
            var sum = 0.0
            for (j in 0..k) {
                let xij = Float64(testData[i][j])
                sum += xij * (xij - 1.0)
            }
            Pbar += sum / (Float64(n) * Float64(n - 1))
        }
        Pbar /= Float64(N)

        var Pebar = 0.0
        for (j in 0..k) {
            Pebar += pj[j] * pj[j]
        }

        if (abs(Pebar - 1.0) < 1e-10) {
            return 1.0
        }

        return (Pbar - Pebar) / (1.0 - Pebar)
    }
}

