import std.collection.ArrayList
import std.regex.Regex

class LongestWord {
    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        if (this.word_list.isEmpty()) {
            return ""
        }

        let r = Regex(#"[^\w\s]"#)
        let cleaned_sentence = r.replaceAll(sentence, "")
        let words = cleaned_sentence.split(#"\s+"#)

        var longest_word = ""
        for (word in words) {
            if (this.word_list.contains(word) && word.length() > longest_word.length()) {
                longest_word = word
            }
        }

        return longest_word
    }
}

