class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let left = center - diff
        let right = center + diff
        if (left < 0 || right >= string.length) {
            return diff - 1
        }
        if (string[left] == string[right]) {
            return palindromic_length(center, diff + 1, string)
        } else {
            return diff - 1
        }
    }

    public func palindromic_string(): String {
        let processed_string = this.input_string.split("").join("|")
        let length = processed_string.length
        let palindromic_lengths: Array<Int64> = Array(length, 0)
        var max_length = 0
        var center_index = 0
        var right_boundary = 0
        var center = 0

        for (index in 0 ..< length) {
            let mirror = 2 * center - index
            if (index < right_boundary) {
                palindromic_lengths[index] = min(right_boundary - index, palindromic_lengths[mirror])
            }
            let length_from_current = palindromic_length(index, palindromic_lengths[index] + 1, processed_string)
            palindromic_lengths[index] = length_from_current

            if (index + length_from_current > right_boundary) {
                center = index
                right_boundary = index + length_from_current
            }

            if (length_from_current > max_length) {
                max_length = length_from_current
                center_index = index
            }
        }

        let start = (center_index - max_length) / 2
        let end = start + max_length
        return this.input_string[start ..< end]
    }
}

