import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var result = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z ]+")

        for str in string_list {
            var clean_str = regex.replace(str, "")
            clean_str = clean_str.trim().toLower()
            let words = ArrayList<String>(clean_str.split(" ").filter((s: String) => !s.isBlank()))
            if words.size() > 0 {
                result.add(words)
            }
        }
        return result
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq_map = HashMap<String, Int64>()

        for words in words_list {
            for word in words {
                if freq_map.containsKey(word) {
                    freq_map.put(word, freq_map.get(word)! + 1)
                } else {
                    freq_map.put(word, 1)
                }
            }
        }

        let sorted_entries = freq_map.entries().collectArrayList()
        sorted_entries.sort((a, b) -> b.value.compare(a.value))  // descending order by frequency

        let top5 = HashMap<String, Int64>()
        let limit = sorted_entries.size() < 5 ? sorted_entries.size() : 5
        for i in 0 ..< limit {
            let entry = sorted_entries[i]
            top5.put(entry.key, entry.value)
        }

        return top5
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

