        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            case Option.Some(value) => {
                return this.format_string(value)
            }
            case Option.None => {
                return ""
            }
        }
    }

    public func format_string(x: String): String {
        if x.isEmpty {
            return ""
        }

        let parts = x.split('.')
        let integerPart = parts[0]
        let decimalPart = if parts.length > 1 then parts[1] else ""

        let integerWords = this.convert_integer(integerPart)
        let decimalWords = if !decimalPart.isEmpty then " AND " + this.convert_decimal(decimalPart) + " ONLY" else " ONLY"

        return integerWords + decimalWords
    }

    private func convert_integer(value: String): String {
        if value == "0" {
            return "ZERO"
        }

        var cleanedValue = value.trimStart('0')
        if cleanedValue.isEmpty {
            cleanedValue = "0"
        }

        let length = cleanedValue.length
        let groups = (length + 2) / 3
        var paddedValue = ""
        for _ in 0..<((groups * 3) - length) {
            paddedValue += "0"
        }
        paddedValue += cleanedValue

        var result = ""
        var index = 0
        while index < groups {
            let start = index * 3
            let end = start + 3
            let segment = paddedValue.substring(start, end)
            if segment != "000" {
                result += this.trans_three(segment)
                if index < groups - 1 {
                    result += " " + this.parse_more(groups - 1 - index) + " "
                }
            }
            index += 1
        }

        return result.trim()
    }

    private func convert_decimal(value: String): String {
        var result = ""
        for ch in value {
            let digit = Int64.parse(String(ch), radix: 10)
            result += this.NUMBER[digit] + " "
        }
        return result.trim()
    }

    public func trans_two(s: String): String {
        let num = Int64.parse(s, radix: 10)
        if num < 10 {
            return this.NUMBER[num]
        } else if num < 20 {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let ones = num % 10
            if ones == 0 {
                return this.NUMBER_TEN[tens - 1]
            } else {
                return this.NUMBER_TEN[tens - 1] + " " + this.NUMBER[ones]
            }
        }
    }

    public func trans_three(s: String): String {
        let num = Int64.parse(s, radix: 10)
        let hundreds = num / 100
        let remainder = num % 100
        var result = ""
        if hundreds > 0 {
            result += this.NUMBER[hundreds] + " HUNDRED"
            if remainder > 0 {
                result += " AND "
            }
        }
        if remainder > 0 {
            result += this.trans_two(String(remainder))
        }
        return result
    }

    public func parse_more(i: Int64): String {
        if i < this.NUMBER_MORE.length {
            return this.NUMBER_MORE[i]
        } else {
            return ""
        }
    }
}
