import std.convert.RadixConvertible
import std.unicode.*

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        var result = ArrayList<Rune>()
        var i = 0
        while i < string.size() {
            if string[i] == r'&' and i + 1 < string.size() and string[i + 1] == r'#' {
                var j = i + 2
                var is_hex = false
                if j < string.size() and (string[j] == r'x' or string[j] == r'X') {
                    is_hex = true
                    j += 1
                }
                var start = j
                while j < string.size() and string[j] != r';' {
                    j += 1
                }
                if j < string.size() and string[j] == r';' {
                    var num_str = string.substring(start, j)
                    var base = if is_hex 16 else 10
                    if let code = num_str.toLong(base) {
                        if code >= 0 and code <= 0x10FFFF {
                            result.append(Rune(code))
                        } else {
                            result.append(r'&')
                            result.append(r'#')
                            if is_hex {
                                result.append(r'x')
                            }
                            for k in start ..< j {
                                result.append(string[k])
                            }
                            result.append(r';')
                        }
                    } else {
                        result.append(r'&')
                        result.append(r'#')
                        if is_hex {
                            result.append(r'x')
                        }
                        for k in start ..< j {
                            result.append(string[k])
                        }
                        result.append(r';')
                    }
                    i = j + 1
                } else {
                    result.append(string[i])
                    i += 1
                }
            } else {
                result.append(string[i])
                i += 1
            }
        }
        return String(result)
    }

    public static func is_hex_char(char: Rune): Bool {
        return (char >= r'0' and char <= r'9') or
               (char >= r'a' and char <= r'f') or
               (char >= r'A' and char <= r'F')
    }
}

