import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        /*
        Initialize the push box game with the map and various attributes.
        :param map: ArrayList<ArrayList<String>>, the map of the push box game, represented as a list of strings. 
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])
        >>> game = PushBoxGame(map) 
        */
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            /*
            Initialize the game by setting the positions of the player, targets, and boxes based on the map.
            >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
            >>> game.targets
            [[3, 3]]
            >>> game.boxes
            [[2, 2]]
            >>> game.player_row
            1
            >>> game.player_col
            1
            */
            for (row_idx, row) in enumerate(this.map) {
                for (col_idx, cell) in enumerate(row) {
                    when (cell) {
                        "O" -> {
                            this.player_row = row_idx
                            this.player_col = col_idx
                        }
                        "G" -> {
                            this.targets.add(ArrayList<Int64>([row_idx, col_idx]))
                            this.target_count += 1
                        }
                        "X" -> {
                            this.boxes.add(ArrayList<Int64>([row_idx, col_idx]))
                        }
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        /*
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of this.is_game_over.
        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        var count: Int64 = 0
        for box in this.boxes {
            for target in this.targets {
                if box == target {
                    count += 1
                    break
                }
            }
        }
        this.is_game_over = (count == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        var delta_row: Int64 = 0
        var delta_col: Int64 = 0

        when (direction) {
            "w" -> delta_row = -1
            "s" -> delta_row = 1
            "a" -> delta_col = -1
            "d" -> delta_col = 1
            else -> return false
        }

        let new_row = this.player_row + delta_row
        let new_col = this.player_col + delta_col

        // Check boundaries
        if new_row < 0 || new_row >= this.map.size() || new_col < 0 || new_col >= this.map.at!(new_row).size() {
            return false
        }

        let next_cell = this.map.at!(new_row).at!(new_col)

        // Wall
        if next_cell == "#" {
            return false
        }

        var is_box: Bool = false
        var box_index: Int64 = -1
        for (index, box) in enumerate(this.boxes) {
            if box.at!(0) == new_row && box.at!(1) == new_col {
                is_box = true
                box_index = index
                break
            }
        }

        if is_box {
            let box_new_row = new_row + delta_row
            let box_new_col = new_col + delta_col

            // Check box boundary
            if box_new_row < 0 || box_new_row >= this.map.size() || box_new_col < 0 || box_new_col >= this.map.at!(box_new_row).size() {
                return false
            }

            let box_next_cell = this.map.at!(box_new_row).at!(box_new_col)

            // Wall or another box
            if box_next_cell == "#" {
                return false
            }

            var is_another_box: Bool = false
            for other_box in this.boxes {
                if other_box.at!(0) == box_new_row && other_box.at!(1) == box_new_col {
                    is_another_box = true
                    break
                }
            }

            if is_another_box {
                return false
            }

            // Move box
            this.boxes.at!(box_index).at!(0) = box_new_row
            this.boxes.at!(box_index).at!(1) = box_new_col
        }

        // Move player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }

    public func print_map(): Unit {
        let display_map = ArrayList<ArrayList<String>>()
        for row in this.map {
            display_map.add(ArrayList<String>(row))
        }

        display_map.at!(this.player_row).at!(this.player_col) = "O"

        for target in this.targets {
            let r = target.at!(0)
            let c = target.at!(1)
            if display_map.at!(r).at!(c) == " " {
                display_map.at!(r).at!(c) = "G"
            }
        }

        for box in this.boxes {
            let r = box.at!(0)
            let c = box.at!(1)
            if display_map.at!(r).at!(c) == " " || display_map.at!(r).at!(c) == "G" {
                display_map.at!(r).at!(c) = "X"
            }
        }

        for row in display_map {
            println(row.collectString(" "))
        }
    }
}

