        false
        >>> game.move('d') 
        true
        */
        var delta_row: Int64 = 0
        var delta_col: Int64 = 0

        when (direction) {
            "w" -> delta_row = -1
            "s" -> delta_row = 1
            "a" -> delta_col = -1
            "d" -> delta_col = 1
            else -> return false
        }

        let new_row = this.player_row + delta_row
        let new_col = this.player_col + delta_col

        // Check boundaries
        if new_row < 0 || new_row >= this.map.size() || new_col < 0 || new_col >= this.map.at!(new_row).size() {
            return false
        }

        let next_cell = this.map.at!(new_row).at!(new_col)

        // Wall
        if next_cell == "#" {
            return false
        }

        var is_box: Bool = false
        var box_index: Int64 = -1
        for (index, box) in enumerate(this.boxes) {
            if box.at!(0) == new_row && box.at!(1) == new_col {
                is_box = true
                box_index = index
                break
            }
        }

        if is_box {
            let box_new_row = new_row + delta_row
            let box_new_col = new_col + delta_col

            // Check box boundary
            if box_new_row < 0 || box_new_row >= this.map.size() || box_new_col < 0 || box_new_col >= this.map.at!(box_new_row).size() {
                return false
            }

            let box_next_cell = this.map.at!(box_new_row).at!(box_new_col)

            // Wall or another box
            if box_next_cell == "#" {
                return false
            }

            var is_another_box: Bool = false
            for other_box in this.boxes {
                if other_box.at!(0) == box_new_row && other_box.at!(1) == box_new_col {
                    is_another_box = true
                    break
                }
            }

            if is_another_box {
                return false
            }

            // Move box
            this.boxes.at!(box_index).at!(0) = box_new_row
            this.boxes.at!(box_index).at!(1) = box_new_col
        }

        // Move player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }

    public func print_map(): Unit {
        let display_map = ArrayList<ArrayList<String>>()
        for row in this.map {
            display_map.add(ArrayList<String>(row))
        }

        display_map.at!(this.player_row).at!(this.player_col) = "O"

        for target in this.targets {
            let r = target.at!(0)
            let c = target.at!(1)
            if display_map.at!(r).at!(c) == " " {
                display_map.at!(r).at!(c) = "G"
            }
        }

        for box in this.boxes {
            let r = box.at!(0)
            let c = box.at!(1)
            if display_map.at!(r).at!(c) == " " || display_map.at!(r).at!(c) == "G" {
                display_map.at!(r).at!(c) = "X"
            }
        }

        for row in display_map {
            println(row.collectString(" "))
        }
    }
}
