            items[item] = Item(price, quantity)
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            let existingItem = items[item]!
            let newQuantity = existingItem.quantity - quantity
            if (newQuantity <= 0) {
                items.remove(item)
            } else {
                items[item] = Item(existingItem.price, newQuantity)
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for ((_, item)) in items.toArray() {
            total = total + (item.price * Float64(item.quantity))
        }
        return total
    }
}
