import std.collection.ArrayList
import std.regex.Regex

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex(#"[.?!]\s+"#)
        let splits = regex.split(sentences_string)
        let result = ArrayList<String>()

        var i = 0
        while (i < splits.size) {
            let part = splits.get(i)
            if (part.endsWith(".") && !part.contains("Mr.")) {
                result.add(part + ".")
            } else if (part.endsWith("?")) {
                result.add(part + "?")
            } else {
                if (i + 1 < splits.size) {
                    let nextPart = splits.get(i + 1)
                    if (nextPart.startsWith(" ")) {
                        result.add(part + nextPart)
                        i += 1
                    } else {
                        result.add(part)
                    }
                } else {
                    result.add(part)
                }
            }
            i += 1
        }
        return result
    }

    public func count_words(sentence: String): Int64 {
        let trimmed = sentence.trim()
        if (trimmed.isEmpty()) {
            return 0
        }
        let words = trimmed.split()
        var count = 0
        for (word in words) {
            var isWord = false
            for (ch in word) {
                if (ch.isLetter()) {
                    isWord = true
                    break
                }
            }
            if (isWord) {
                count += 1
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var maxWords = 0
        for (sentence in sentences) {
            let wordCount = count_words(sentence)
            if (wordCount > maxWords) {
                maxWords = wordCount
            }
        }
        return maxWords
    }
}

