        var key_str = ""
        var val_str = ""
        for (i in 0..keys.size) {
            if (i > 0) {
                key_str += ", "
                val_str += ", "
            }
            key_str += keys[i]
            val_str += "'" + values[i] + "'"
        }
        return "INSERT INTO ${this.table_name} (${key_str}) VALUES (${val_str});"
