import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    /*
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    */

    public static func median(data: ArrayList<Int64>): Float64 {
        if data.isEmpty() {
            return 0.0
        }
        let sortedData = data.clone()
        sort(sortedData)
        let n = sortedData.size()
        if n % 2 == 1 {
            return Float64(sortedData.get(Int64(n / 2)))
        } else {
            let mid1 = sortedData.get(Int64(n / 2 - 1))
            let mid2 = sortedData.get(Int64(n / 2))
            return Float64(mid1 + mid2) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequencyMap = HashMap<Int64, Int64>()
        for (value in data) {
            if let count = frequencyMap.get(value) {
                frequencyMap.put(value, count + 1)
            } else {
                frequencyMap.put(value, 1)
            }
        }

        let maxCount = frequencyMap.values().max()
        let result = ArrayList<Int64>()
        for (entry in frequencyMap) {
            if entry.second == maxCount {
                result.add(entry.first)
            }
        }

        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if x.size() != y.size() || x.size() == 0 {
            return None
        }

        let meanXOpt = mean(x)
        let meanYOpt = mean(y)

        if meanXOpt is None || meanYOpt is None {
            return None
        }

        let meanX = meanXOpt as Float64
        let meanY = meanYOpt as Float64

        var numerator: Float64 = 0.0
        var denomX: Float64 = 0.0
        var denomY: Float64 = 0.0

        for (i in 0..<x.size()) {
            let xi = Float64(x.get(i))
            let yi = Float64(y.get(i))

            let diffX = xi - meanX
            let diffY = yi - meanY

            numerator += diffX * diffY
            denomX += diffX * diffX
            denomY += diffY * diffY
        }

        if denomX == 0.0 || denomY == 0.0 {
            return None
        }

        let denominator = sqrt(denomX * denomY)
        if denominator == 0.0 {
            return None
        }

        return Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.isEmpty() {
            return None
        }

        var sum: Int64 = 0
        for (value in data) {
            sum += value
        }
        return Some(Float64(sum) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let size = data.size()
        let result = ArrayList<ArrayList<Float64>>()

        for (i in 0..<size) {
            let row = ArrayList<Float64>()
            for (j in 0..<size) {
                if i == j {
                    row.add(1.0)
                } else {
                    let corrOpt = correlation(data.get(i), data.get(j))
                    if corrOpt is Some<Float64> {
                        row.add(corrOpt as Float64)
                    } else {
                        row.add(0.0)
                    }
                }
            }
            result.add(row)
        }

        return result
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanOpt = mean(data)
        if meanOpt is None {
            return None
        }

        let meanValue = meanOpt as Float64
        var sumSquaredDiff: Float64 = 0.0
        for (value in data) {
            let diff = Float64(value) - meanValue
            sumSquaredDiff += diff * diff
        }

        let variance = sumSquaredDiff / Float64(data.size())
        return Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanOpt = mean(data)
        let stdDevOpt = standard_deviation(data)

        if meanOpt is None || stdDevOpt is None {
            return None
        }

        let meanValue = meanOpt as Float64
        let stdDevValue = stdDevOpt as Float64

        if stdDevValue == 0.0 {
            return None
        }

        let result = ArrayList<Float64>()
        for (value in data) {
            let z = (Float64(value) - meanValue) / stdDevValue
            result.add(z)
        }

        return Some(result)
    }
}

