                        row.add(0.0)
                    }
                }
            }
            result.add(row)
        }

        return result
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanOpt = mean(data)
        if meanOpt is None {
            return None
        }

        let meanValue = meanOpt as Float64
        var sumSquaredDiff: Float64 = 0.0
        for (value in data) {
            let diff = Float64(value) - meanValue
            sumSquaredDiff += diff * diff
        }

        let variance = sumSquaredDiff / Float64(data.size())
        return Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanOpt = mean(data)
        let stdDevOpt = standard_deviation(data)

        if meanOpt is None || stdDevOpt is None {
            return None
        }

        let meanValue = meanOpt as Float64
        let stdDevValue = stdDevOpt as Float64

        if stdDevValue == 0.0 {
            return None
        }

        let result = ArrayList<Float64>()
        for (value in data) {
            let z = (Float64(value) - meanValue) / stdDevValue
            result.add(z)
        }

        return Some(result)
    }
}
