class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        return this.portfolio.removeFirst(stock)
    }

    public func buy_stock(stock: Stock): Bool {
        let totalCost = stock.price * Float64(stock.quantity)
        if this.cash_balance >= totalCost {
            this.cash_balance = this.cash_balance - totalCost
            this.add_stock(stock)
            return true
        } else {
            return false
        }
    }

    public func sell_stock(stock: Stock): Bool {
        let index = this.portfolio.findFirstIndex((s) -> s == stock)
        if let i = index {
            let existingStock = this.portfolio[i]
            if existingStock.quantity >= stock.quantity {
                let totalValue = stock.price * Float64(stock.quantity)
                this.cash_balance = this.cash_balance + totalValue

                if existingStock.quantity == stock.quantity {
                    this.portfolio.removeAt(i)
                } else {
                    existingStock.quantity = existingStock.quantity - stock.quantity
                }
                return true
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var totalValue: Float64 = this.cash_balance
        for stock in this.portfolio {
            totalValue = totalValue + (stock.price * Float64(stock.quantity))
        }
        return totalValue
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let summaryList = ArrayList<HashMap<String, Any>>()
        for stock in this.portfolio {
            let map = HashMap<String, Any>()
            map["name"] = stock.name
            map["value"] = stock.price * Float64(stock.quantity)
            summaryList.add(map)
        }
        return (this.calculate_portfolio_value(), summaryList)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }
}

